<template><a-card class="panel-card form-card"><a-form layout="vertical" :model="form" @finish="save"><a-row :gutter="16"><a-col :xs="24" :md="12"><a-form-item label="STRM 基础地址" required><a-input v-model:value="form.strm_base_url"/></a-form-item></a-col><a-col :xs="24" :md="12"><a-form-item label="Cron 表达式" required><a-input v-model:value="form.cron"/></a-form-item></a-col><a-col :xs="24" :md="12"><a-form-item label="最小视频大小（MB）"><a-input-number v-model:value="minSize" :min="0" style="width:100%"/></a-form-item></a-col><a-col :xs="24" :md="12"><a-form-item label="本地代理"><a-switch v-model:checked="localProxy"/></a-form-item></a-col></a-row><a-form-item label="视频扩展名"><a-select v-model:value="form.video_ext_arr" mode="tags"/></a-form-item><a-form-item label="元数据扩展名"><a-select v-model:value="form.meta_ext_arr" mode="tags"/></a-form-item><a-form-item label="排除名称"><a-select v-model:value="form.exclude_name_arr" mode="tags"/></a-form-item><a-row :gutter="16"><a-col v-for="field in selects" :key="field.key" :span="12"><a-form-item :label="field.label"><a-select v-model:value="form[field.key]" :options="field.options"/></a-form-item></a-col></a-row><a-checkbox v-model:checked="checkMtime">检查元数据修改时间</a-checkbox><div style="margin-top:24px"><a-button type="primary" html-type="submit" :loading="saving">保存设置</a-button></div></a-form></a-card></template><script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{message}from'ant-design-vue';import{get,post}from'../../services/http';import type{AnyMap}from'../../types';const form=reactive<AnyMap>({video_ext_arr:[],meta_ext_arr:[],exclude_name_arr:[]}),minSize=ref(0),localProxy=ref(false),checkMtime=ref(false),saving=ref(false);const boolOpts=[{value:0,label:'关闭'},{value:1,label:'开启'}],selects=[{key:'download_meta',label:'下载元数据',options:boolOpts},{key:'upload_meta',label:'上传元数据',options:[...boolOpts,{value:2,label:'删除远端'}]},{key:'delete_dir',label:'删除空目录',options:boolOpts},{key:'add_path',label:'添加媒体路径',options:[{value:1,label:'添加'},{value:2,label:'不添加'}]}];onMounted(async()=>{Object.assign(form,await get('/setting/strm-config'));minSize.value=Math.round((form.min_video_size||0)/1048576);localProxy.value=form.local_proxy===1;checkMtime.value=form.check_meta_mtime===1});async function save(){saving.value=true;try{await post('/setting/strm-config',{...form,min_video_size:minSize.value*1048576,local_proxy:localProxy.value?1:0,check_meta_mtime:checkMtime.value?1:0});message.success('STRM 设置已保存')}finally{saving.value=false}}</script>
